from playwright.sync_api import sync_playwright
from PIL import Image
from pathlib import Path
import tempfile,json,os,copy
fixture=json.loads((ROOT/'tests/fixtures/worker-1.json').read_text());engine=os.getenv('PS_TEST_ENGINE','chromium')
shim='''(()=>{window.cameraSize={width:1600,height:900};const source=document.createElement('canvas');const draw=CanvasRenderingContext2D.prototype.drawImage;CanvasRenderingContext2D.prototype.drawImage=function(image,...args){if(image instanceof HTMLVideoElement){const {width:w,height:h}=cameraSize;source.width=w;source.height=h;const c=source.getContext('2d');c.fillStyle='#445566';c.fillRect(0,0,w,h);for(const [x,y,color]of [[0,0,'#ff0000'],[w-60,0,'#00ff00'],[0,h-60,'#0000ff'],[w-60,h-60,'#ffff00']]){c.fillStyle=color;c.fillRect(x,y,60,60)}image=source}return draw.call(this,image,...args)};Object.defineProperty(HTMLVideoElement.prototype,'videoWidth',{get:()=>cameraSize.width});Object.defineProperty(HTMLVideoElement.prototype,'videoHeight',{get:()=>cameraSize.height});Object.defineProperty(HTMLVideoElement.prototype,'srcObject',{configurable:true,get(){return this._fake},set(v){this._fake=v}});HTMLVideoElement.prototype.play=async()=>{};Object.defineProperty(navigator,'mediaDevices',{configurable:true,value:{getUserMedia:async constraints=>{window.lastConstraints=constraints;return {getTracks:()=>[{stop(){}}]}}}});Object.defineProperty(navigator,'geolocation',{configurable:true,value:{getCurrentPosition(ok){ok({coords:{latitude:22.6,longitude:120.5,accuracy:5},timestamp:Date.now()})}}})})();'''
