 browser=p.chromium.launch(executable_path=CHROMIUM,args=['--no-sandbox']) if engine=='chromium' else p.webkit.launch();ctx=browser.new_context(viewport={'width':390,'height':844},is_mobile=True,accept_downloads=True);ctx.add_init_script(shim);ctx.route('https://tile.openstreetmap.org/**',lambda r:r.abort());ctx.route('**/data/worker-1.json',lambda r:r.fulfill(json=fixture));pg=ctx.new_page();pg.clock.set_fixed_time(QA_NOW);errors=[];pg.on('pageerror',lambda e:errors.append(str(e)));pg.goto(BASE+'worker-1.html');pg.wait_for_function('PSApp.state.tasks.length>0');pg.locator('.task-content').first.click()
 for selector in ['#worker-board','#worker-open-task','#pin-mode']:assert pg.locator(selector).count()==0
 captures=[]
 for i,(width,height) in enumerate([(390,844),(844,390)]):
  pg.set_viewport_size({'width':width,'height':height});pg.click('#worker-camera');pg.wait_for_function('!document.querySelector("#shutter").disabled');assert pg.evaluate('getComputedStyle(document.querySelector("#video")).objectFit')=='contain';assert pg.evaluate('lastConstraints.video.aspectRatio===undefined&&lastConstraints.video.resizeMode.ideal==="none"')
  pg.click('#shutter');pg.wait_for_function('!document.querySelector("#capture-save").hidden')
  with pg.expect_download() as dl:pg.click('#capture-save')
  dest=Path(temp)/f'capture-{i}.jpg';dl.value.save_as(str(dest));im=Image.open(dest);assert im.size==(1600,900),im.size
  for point,color in [((8,8),(255,0,0)),((1591,8),(0,255,0)),((8,891),(0,0,255)),((1591,891),(255,255,0))]:assert max(abs(a-b) for a,b in zip(im.getpixel(point),color))<15,(point,im.getpixel(point))
  captures.append(im.size);pg.click('#camera-back');pg.wait_for_selector('#detail-board');pg.click('#close-dialog')
 vendor=copy.deepcopy(fixture);vendor['person']={'id':'v1','name':'示範廠商'};vendor['vendorType']='雜草垃圾';vendor['tasks']=[{**vendor['tasks'][0],'type':'雜草垃圾'}];ctx.route('**/data/vendor-1.json',lambda r:r.fulfill(json=vendor));vp=ctx.new_page();vp.on('pageerror',lambda e:errors.append(str(e)));vp.goto(BASE+'vendor-1.html');vp.wait_for_function('PSApp.state.tasks.length===1');vp.locator('.task-content').first.click()
 for selector in ['#worker-board','#worker-open-task','#pin-mode']:assert vp.locator(selector).count()==0
 assert vp.locator('#worker-camera').is_visible() and vp.locator('#worker-navigate').is_visible() and vp.locator('#fit-map').is_visible() and vp.locator('#field-locate').is_visible();vp.locator('[data-detail]').first.click();assert vp.locator('#detail-board').is_visible()
 assert not errors,errors;result={'engine':engine,'red_cross_map_actions_removed':True,'detail_whiteboard_preserved':True,'full_native_16_9_frames':captures,'four_edge_markers_preserved':True,'portrait_and_landscape_viewports':True,'camera_navigation_reset_gps_preserved':True,'errors':errors};out=ROOT/'evidence/uncropped';out.mkdir(parents=True,exist_ok=True);(out/f'{engine}.json').write_text(json.dumps(result,ensure_ascii=False,indent=2));print(json.dumps(result,ensure_ascii=False,indent=2));browser.close()
